 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            comps.append((color, cells))
    stable = [[False] * w for _ in range(h)]
    for color, cells in comps:
        if len(cells) > 1:
            for r, c in cells:
                stable[r][c] = True
    out = [row[:] for row in grid]
    for color, cells in comps:
        if len(cells) != 1:
            continue
        r, c = cells[0]
        # Use the nearest ring of cells belonging to coherent (non-singleton) regions.
        for radius in range(1, max(h, w) + 1):
            votes = Counter()
            for y in range(max(0, r-radius), min(h, r+radius+1)):
                for x in range(max(0, c-radius), min(w, c+radius+1)):
                    if abs(y-r) + abs(x-c) == radius and stable[y][x]:
                        votes[grid[y][x]] += 1
            if votes:
                out[r][c] = votes.most_common(1)[0][0]
                break
    return out

