def transform(grid):
    h, w = len(grid), len(grid[0])
    # Connected components of each color; singleton components are corrupting
    # one-cell marks. Recover them from the immediate neighborhood.
    seen = [[False] * w for _ in range(h)]
    singletons = set()
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            component_size = 0
            while q:
                y, x = q.popleft()
                component_size += 1
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if component_size == 1:
                singletons.add((r, c))

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, c in singletons:
        # Cardinal neighbors strongly identify a cell punched out of a block.
        cardinal = Counter(grid[y][x] for y, x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                           if 0 <= y < h and 0 <= x < w and (y,x) not in singletons)
        if cardinal:
            top = max(cardinal.values())
            tied = [color for color, n in cardinal.items() if n == top]
            # For the demo's ambiguity, prefer the non-background when it is
            # tied with the background (a single marker inside a structure).
            if len(tied) == 1:
                out[r][c] = tied[0]
                continue
            objects = [color for color in tied if color != background]
            if objects:
                out[r][c] = objects[0]
                continue
        # Otherwise remove isolated specks by 3x3 local majority.
        votes = Counter(grid[y][x] for y in range(max(0,r-1), min(h,r+2))
                        for x in range(max(0,c-1), min(w,c+2))
                        if (y,x) != (r,c) and (y,x) not in singletons)
        if votes:
            top = max(votes.values())
            tied = [color for color, n in votes.items() if n == top]
            out[r][c] = background if background in tied else tied[0]
    return out
